    const M = mod.plan.motor; const n = Math.max(1, Math.round((rSem(Date.now()) - M.inicio)/(7*DIA_MS))+1); const tot = mod.plan.totalWeeks || 12;
    if((mod.setup||{}).raceDate) return { wk: Math.min(n, tot), total: tot, cycle:1 };
