['piAlterar','piPreset'].forEach(f=>{ const o = window[f]; if(typeof o !== 'function') return; window[f] = function(){ if(!mtTem('inicioCompleto')) return mtPremiumAviso('inicioCompleto'); return o.apply(this, arguments); }; });

